context.handlebars.registerHelper("priority", priority => {
  if (priority === 2) return "lead";
  if (priority === 1) return "lag";
  return "standby";
})

context.handlebars.registerHelper("state", (run, trip) => {
  if (trip == 1) return "tripped";

  return run == 1 ? "running" : "stopped";
})

context.handlebars.registerHelper("stateClass", (run, trip) => {
  if (trip == 1) return "trip";

  return run == 1 ? "running" : "stopped";
})
context.handlebars.registerHelper('numberFormat', function (value, options) {
  if (value == null) return '--';
  // Helper parameters
  var dl = options.hash['decimalLength'] || 2;
  var ts = options.hash['thousandsSep'] || ',';
  var ds = options.hash['decimalSep'] || '.';

  // Parse to float
  var value = parseFloat(value);

  // The regex
  var re = '\\d(?=(\\d{3})+' + (dl > 0 ? '\\D' : '$') + ')';

  // Formats the number with the decimals
  var num = value.toFixed(Math.max(0, ~~dl));

  // Returns the formatted number
  return (ds ? num.replace('.', ds) : num).replace(new RegExp(re, 'g'), '$&' + ts);
});

context.handlebars.registerHelper('alarmClass', activeAlarms => {
  if (activeAlarms === 0) return 'ok';
  if (activeAlarms === 1) return 'warn';
  return 'bad'
})

context.handlebars.registerHelper('runTime', runtime => {
  const hour = Math.floor(runtime / 60);
  const min = Math.round(runtime % 60);
  return `${hour}h ${min}m`
})

context.handlebars.registerHelper('assignedChr', value => {
  if (!value) return 'not assigned';
  return 'serving ' + value;
})

context.handlebars.registerHelper('autoBadge', (autoMode, controlMode) => {
  if (autoMode === 1 && controlMode === "AUTO") { 
    return `<span class="pump-status-mode auto">AUTO</span>`;
  }

  let result = '';

  if (autoMode === 0) {
    result += `<span class="pump-status-mode manual">MANUAL</span>`
  }
  if (controlMode !== 'AUTO') {
    result += `<span class="pump-status-mode remote">REMOTE</span>`
  }

  return result;
})

